coding.referenceSolution:
interface Product { name: string; category: string; price: number; stock: number }
interface Filters { category?: string; minPrice?: number; maxPrice?: number; inStock?: boolean }

function applyFilters(products: Product[], f: Filters): string[] {
  const checks: ((p: Product) => boolean)[] = [];
  if (f.category !== undefined) checks.push((p) => p.category === f.category);
  if (f.minPrice !== undefined) checks.push((p) => p.price >= f.minPrice!);
  if (f.maxPrice !== undefined) checks.push((p) => p.price <= f.maxPrice!);
  if (f.inStock) checks.push((p) => p.stock > 0);
  return products.filter((p) => checks.every((check) => check(p))).map((p) => p.name);
}

