coding.referenceSolution:
function buildTree(items) {
  const nodes = new Map(items.map((i) => [i.id, { id: i.id, name: i.name, children: [] }]));
  const roots = [];
  for (const item of items) {
    const parent = item.parentId === null ? null : nodes.get(item.parentId);
    (parent ? parent.children : roots).push(nodes.get(item.id));
  }
  const sortDeep = (list) => {
    list.sort((a, b) => a.name.localeCompare(b.name));
    list.forEach((n) => sortDeep(n.children));
    return list;
  };
  return sortDeep(roots);
}

