function diffById(prev, next) {
  const before = new Map(prev.map((p) => [p.id, p]));
  const after = new Map(next.map((n) => [n.id, n]));
  return {
    added: next.filter((n) => !before.has(n.id)).map((n) => n.id),
    removed: prev.filter((p) => !after.has(p.id)).map((p) => p.id),
    updated: next.filter((n) => before.has(n.id) && JSON.stringify(before.get(n.id)) !== JSON.stringify(n)).map((n) => n.id),
  };
}

